def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    background = Counter(x for row in grid for x in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Cells between matching non-background markers in each row or column
    # are filled with 3.
    for r in range(h):
        markers = [c for c in range(w) if grid[r][c] != background]
        for a, b in zip(markers, markers[1:]):
            if grid[r][a] == grid[r][b]:
                for c in range(a + 1, b):
                    if grid[r][c] == background:
                        out[r][c] = 3

    for c in range(w):
        markers = [r for r in range(h) if grid[r][c] != background]
        for a, b in zip(markers, markers[1:]):
            if grid[a][c] == grid[b][c]:
                for r in range(a + 1, b):
                    if grid[r][c] == background:
                        out[r][c] = 3
    return out
